import unittest

from calc import divide


class TestDivide(unittest.TestCase):
    def test_regular_division(self):
        self.assertEqual(divide(10, 2), 5)

    def test_zero_divisor(self):
        self.assertIsNone(divide(10, 0))


if __name__ == "__main__":
    unittest.main()
